// VTABLE LAYOUT & DISPATCH MECHANISM

class Base {
// Hidden vptr (pointer to vtable) is the first member
public:
    virtual void step_one(); // VTable[0]
    virtual void step_two(); // VTable[1]
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    void step_one() override; // Overrides VTable[0]
    // step_two remains Base::step_two in VTable[1]
};

// Dispatch: Look up required index (offset) in object's vtable
Base* p = new Derived();

// 1. Get p->vptr (offset 0)
// 2. Get vtable (*(p->vptr))
// 3. Get function address (vtable[index])
p->step_one(); // Dynamic dispatch via VTable[0] (calls Derived::step_one)
p->step_two(); // Dynamic dispatch via VTable[1] (calls Base::step_two)

delete p;
